{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich palm oil, a lipophilic chromanol with an isoprenoid side chain structurally closest to CoQ10, has poor oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene, a long polyisoprenoid carotenoid, showed only 0.17% systemic availability after oral tomato paste in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Synthetic lycopene dispersed in oil yielded about 1.2% of the dose in blood circulation in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene absolute bioavailability was estimated at 58.5 ± 18.9% in humans, a high value for a related acyclic carotenoid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "In a 13C-lycopene study, all-trans lycopene bioavailability was 23.2 ± 8%, above the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a polyprenylated natural product, showed high oral bioavailability from an extract.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ubiquinone-10 (CoQ10), a highly lipophilic benzoquinone with a 10-unit polyisoprenyl tail. Its established oral bioavailability is low, and the closest transferable evidence (tocotrienols, lycopene) indicates poor absorption; the few high values in related carotenoids do not overcome the physicochemical and pharmacokinetic liabilities.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for CoQ10 is present in the provided records.",
    "Formulation and food effects, which strongly modulate CoQ10 absorption, are not specified for the query.",
    "High phytoene bioavailability may not transfer because phytoene lacks the polar quinone head and has different micellarization/absorption behavior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

